def isValidSudoku_three_pass(board):
    # 第一趟：查每一行
    for r in range(9):
        seen = set()                       # 每行一个新集合
        for c in range(9):
            v = board[r][c]
            if v == '.':                   # 空格不参与校验
                continue
            if v in seen:
                return False
            seen.add(v)
    # 第二趟：查每一列
    for c in range(9):
        seen = set()
        for r in range(9):
            v = board[r][c]
            if v == '.':
                continue
            if v in seen:
                return False
            seen.add(v)
    # 第三趟：查每个 3x3 宫
    for br in range(0, 9, 3):              # 宫左上角行号
        for bc in range(0, 9, 3):          # 宫左上角列号
            seen = set()
            for dr in range(3):
                for dc in range(3):
                    v = board[br + dr][bc + dc]
                    if v == '.':
                        continue
                    if v in seen:
                        return False
                    seen.add(v)
    return True

