class Solution:
    def isValidSudoku(self, board: List[List[str]]) -> bool:
        seen = {}    # 键 (类型, 编号, 数字)：如 ('r', 0, '5') 表示第 0 行出现过 5
        for r in range(9):
            for c in range(9):
                v = board[r][c]
                if v == '.':                  # 空格不参与校验
                    continue
                b = (r // 3) * 3 + c // 3     # 所属 3x3 宫的编号 0~8
                for key in (('r', r, v), ('c', c, v), ('b', b, v)):
                    if key in seen:           # 行/列/宫任一重复 => 非法
                        return False
                    seen[key] = True
        return True

