class Solution {
public:
    bool isValidSudoku(vector<vector<char>>& board) {
        // 三套记录：rows[r]、cols[c]、boxes[b] 分别登记对应单元出现过的数字
        vector<array<bool, 9>> rows(9), cols(9), boxes(9);
        for (int r = 0; r < 9; ++r) {
            for (int c = 0; c < 9; ++c) {
                char v = board[r][c];
                if (v == '.') continue;          // 空格不参与校验
                int d = v - '1';                 // 数字 1-9 映射到下标 0-8
                int b = (r / 3) * 3 + c / 3;     // 宫编号 0~8，必背公式
                if (rows[r][d] || cols[c][d] || boxes[b][d])
                    return false;                // 先查：行/列/宫任一重复即非法
                rows[r][d] = cols[c][d] = boxes[b][d] = true;   // 后存：登记三套记录
            }
        }
        return true;
    }
};

