class Solution {
public:
    void rotate(vector<vector<int>>& matrix) {
        int n = (int)matrix.size();
        // 顺时针 90° = 沿主对角线转置 + 每行左右翻转，两步均可原地完成
        // 第一步：沿主对角线转置——只走上三角（j > i），防止交换两次等于没换
        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                swap(matrix[i][j], matrix[j][i]);
            }
        }
        // 第二步：每一行左右翻转（双指针向中间收拢），合成顺时针 90°
        for (auto& row : matrix) {
            reverse(row.begin(), row.end());
        }
    }
};

