class Solution {
    public void rotate(int[][] matrix) {
        int n = matrix.length;
        // 第一步：沿主对角线转置——只走上三角（j > i），防止交换两次等于没换
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int tmp = matrix[i][j];
                matrix[i][j] = matrix[j][i];
                matrix[j][i] = tmp;
            }
        }
        // 第二步：每一行左右翻转（双指针向中间收拢），合成顺时针 90°
        for (int[] row : matrix) {
            int l = 0, r = n - 1;    // 行内双指针：l 指向行首，r 指向行尾
            while (l < r) {
                int tmp = row[l];
                row[l++] = row[r];
                row[r--] = tmp;
            }
        }
    }
}

