class Solution {
public:
    vector<int> spiralOrder(vector<vector<int>>& matrix) {
        vector<int> ans;
        int m = (int)matrix.size(), n = (int)matrix[0].size();
        int t = 0, b = m - 1, l = 0, r = n - 1;    // 上/下/左/右边界
        while (t <= b && l <= r) {
            for (int c = l; c <= r; ++c) ans.push_back(matrix[t][c]);  // ① 上边：左 -> 右
            ++t;
            for (int i = t; i <= b; ++i) ans.push_back(matrix[i][r]);  // ② 右边：上 -> 下
            --r;
            if (t > b) break;      // 剩余的行已输出完，防重复
            for (int c = r; c >= l; --c) ans.push_back(matrix[b][c]);  // ③ 下边：右 -> 左
            --b;
            if (l > r) break;      // 剩余的列已输出完，防重复
            for (int i = b; i >= t; --i) ans.push_back(matrix[i][l]);  // ④ 左边：下 -> 上
            ++l;
        }
        return ans;
    }
};

