func spiralOrder(matrix [][]int) []int {
	m, n := len(matrix), len(matrix[0])
	ans := []int{}
	t, b, l, r := 0, m-1, 0, n-1 // 上/下/左/右边界
	for t <= b && l <= r {
		for c := l; c <= r; c++ { // ① 上边：左 -> 右
			ans = append(ans, matrix[t][c])
		}
		t++
		for i := t; i <= b; i++ { // ② 右边：上 -> 下
			ans = append(ans, matrix[i][r])
		}
		r--
		if t > b { // 剩余的行已输出完，防重复
			break
		}
		for c := r; c >= l; c-- { // ③ 下边：右 -> 左
